SELECT COUNT(*)
  FROM TB_NOTI
 WHERE RCVR_ID = #{receiverId}
   AND PBANC_SN = #{pbancSn}
   AND NOTI_TYPE_CD = #{typeCd}
   AND NOTI_CN LIKE #{tag} || '%'

SELECT COUNT(*)
  FROM TB_NOTI
 WHERE RCVR_ID = #{receiverId}
   AND NOTI_TYPE_CD = #{typeCd}
   AND NOTI_CN = #{content}
   AND CRT_DT >= SYSDATE - 2
